# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">قِصَّةُ يُوسُفَ عَلَيْهِ السَّلَامُ (HZ. YUSUF KISSASININ AŞAMALARI)</text>\n  <!-- Asama 1: Ruya ve Kuyu -->\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">١. الرُّؤْيَا وَالْجُبُّ</text>\n  <text x="125" y="86" text-anchor="middle" font-size="11" font-weight="bold" fill="#3b82f6">(Rüya ve Kuyuya Atılma)</text>\n  <rect x="34" y="98" width="182" height="46" rx="6" fill="#dbeafe"/>\n  <text x="125" y="116" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">أَحَدَ عَشَرَ كَوْكَبًا وَالشَّمْسَ وَالْقَمَرَ</text>\n  <text x="125" y="134" text-anchor="middle" font-size="10.5" fill="#1d4ed8">11 yıldız, güneş ve ayın secdesi</text>\n  <text x="34" y="166" font-size="11" fill="#1e3a8a">• الْحَسَدُ: Kardeşlerin kıskançlığı.</text>\n  <text x="34" y="186" font-size="11" fill="#1e3a8a">• أَلْقَوْهُ فِي غَيَابَتِ الْجُبِّ: Kuyunun</text>\n  <text x="42" y="202" font-size="11" fill="#1e3a8a">dibine bırakılması ve sabır.</text>\n  <!-- Asama 2: Misir ve Zindan -->\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">٢. الصَّبْرُ وَالْعِفَّةُ فِي مِصْرَ</text>\n  <text x="350" y="86" text-anchor="middle" font-size="11" font-weight="bold" fill="#d97706">(Mısır\'da İffet ve Zindan)</text>\n  <rect x="259" y="98" width="182" height="46" rx="6" fill="#fde68a"/>\n  <text x="350" y="116" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">تَأْوِيلُ الْأَحَادِيثِ (Rüya Tabiri)</text>\n  <text x="350" y="134" text-anchor="middle" font-size="10.5" fill="#92400e">İffetini koruyup zindanda tebliğ</text>\n  <text x="259" y="166" font-size="11" fill="#78350f">• السِّجْنُ: Haksız yere hapsedilme.</text>\n  <text x="259" y="186" font-size="11" fill="#78350f">• Hükümdarın rüyasını yorumlayıp</text>\n  <text x="267" y="202" font-size="11" fill="#78350f">7 yıllık kıtlığa tedbir alması.</text>\n  <!-- Asama 3: Aziz Olma ve Af -->\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">٣. عَزِيزُ مِصْرَ وَالْعَفْوُ</text>\n  <text x="575" y="86" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">(Mısır Azizi Olma ve Affetme)</text>\n  <rect x="484" y="98" width="182" height="46" rx="6" fill="#dcfce7"/>\n  <text x="575" y="116" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">خَزَائِنُ الْأَرْضِ (Hazine Yönetimi)</text>\n  <text x="575" y="134" text-anchor="middle" font-size="10.5" fill="#166534">حَفِيظٌ عَلِيمٌ (Koruyan ve Bilen)</text>\n  <text x="484" y="166" font-size="11" fill="#14532d">• الْعَفْوُ: Kardeşlerini bağışlaması.</text>\n  <text x="484" y="186" font-size="11" fill="#14532d">• Ailesinin Mısır\'da kavuşması</text>\n  <text x="492" y="202" font-size="11" fill="#14532d">ve rüyanın gerçekleşmesi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">أُولُو الْعَزْمِ مِنَ الرُّسُلِ (ULU\'L-AZM PEYGAMBERLER VE KISSALARI)</text>\n  <!-- Ust: 5 Ulu\'l-Azm Peygamber -->\n  <rect x="25" y="42" width="650" height="62" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">BEŞ BÜYÜK AZİM VE SABIR PEYGAMBERİ (أُولُو الْعَزْمِ)</text>\n  <text x="350" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#581c87">١. نُوحٌ (Nuh)   —   ٢. إِبْرَاهِيمُ (İbrahim)   —   ٣. مُوسَى (Musa)   —   ٤. عِيسَى (İsa)   —   ٥. مُحَمَّدٌ (Muhammed)</text>\n  <!-- Sol Alt: En\'am 83-86 -->\n  <rect x="25" y="116" width="315" height="128" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="138" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">EN\'ÂM SURESİ 83-86. AYETLER</text>\n  <text x="40" y="160" font-size="11.5" fill="#1e3a8a">• Kur\'an\'da adı geçen 25 peygamberin</text>\n  <text x="48" y="176" font-size="11.5" fill="#1e3a8a">18\'i bu ayetlerde peş peşe zikredilir.</text>\n  <text x="40" y="198" font-size="11.5" fill="#1e3a8a">• Ortak davet: عِبَادَةُ اللَّهِ وَحْدَهُ (Tevhid)</text>\n  <text x="40" y="220" font-size="11.5" font-weight="bold" fill="#1d4ed8">• وَآتَيْنَاهُمْ حُكْمًا وَعِلْمًا (Hikmet ve ilim)</text>\n  <!-- Sag Alt: Hz. Nuh Kissasi -->\n  <rect x="360" y="116" width="315" height="128" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="517" y="138" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">HZ. NUH KISSASI KAVRAMLARI</text>\n  <text x="378" y="160" font-size="11.5" fill="#7c2d12">• Tebliğ süresi: تِسْعَ مِئَةٍ وَخَمْسِينَ عَامًا (950 yıl)</text>\n  <text x="378" y="182" font-size="11.5" fill="#7c2d12">• السَّفِينَةُ / الْفُلْكُ: Kurtuluş gemisi inşası.</text>\n  <text x="378" y="204" font-size="11.5" fill="#7c2d12">• الطُّوفَانُ: İnkârcı kavmin tufanda boğulması.</text>\n  <text x="378" y="226" font-size="11.5" font-weight="bold" fill="#c2410c">• فَاصْبِرْ كَمَا صَبَرَ أُولُو الْعَزْمِ (Ahkâf, 35)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">الْفِعْلُ الْمُجَرَّدُ وَالْفِعْلُ الْمَزِيدُ (MÜCERRED VE MEZÎD FİİLLER)</text>\n  <!-- Sol: Mucerred -->\n  <rect x="20" y="45" width="205" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="122" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">الْفِعْلُ الْمُجَرَّدُ</text>\n  <text x="122" y="86" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">(Sülâsî Mücerred - 3 Harfli)</text>\n  <rect x="34" y="98" width="176" height="42" rx="6" fill="#dcfce7"/>\n  <text x="122" y="116" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">Tüm Harfleri Asli (Kök)</text>\n  <text x="122" y="132" text-anchor="middle" font-size="10.5" fill="#166534">فَعَلَ / فَعِلَ / فَعُلَ</text>\n  <text x="36" y="162" font-size="11.5" fill="#14532d">• كَتَبَ (yazdı)</text>\n  <text x="36" y="182" font-size="11.5" fill="#14532d">• عَلِمَ (bildi)</text>\n  <text x="36" y="202" font-size="11.5" fill="#14532d">• حَفِظَ (korudu)</text>\n  <text x="36" y="222" font-size="11.5" fill="#14532d">• صَبَرَ (sabretti)</text>\n  <!-- Orta: Mezid 1 Harf -->\n  <rect x="240" y="45" width="215" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="347" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">مَزِيدٌ بِحَرْفٍ وَاحِدٍ</text>\n  <text x="347" y="86" text-anchor="middle" font-size="11" font-weight="bold" fill="#3b82f6">(1 Harf Ekli - 4 Harfli)</text>\n  <rect x="254" y="98" width="186" height="42" rx="6" fill="#dbeafe"/>\n  <text x="347" y="116" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">أَفْعَلَ / فَعَّلَ / فَاعَلَ</text>\n  <text x="347" y="132" text-anchor="middle" font-size="10.5" fill="#1d4ed8">Ettirgenlik ve İşteşlik Anlamı</text>\n  <text x="256" y="162" font-size="11.5" fill="#1e3a8a">• أَرْسَلَ (gönderdi) / أَكْرَمَ</text>\n  <text x="256" y="182" font-size="11.5" fill="#1e3a8a">• عَلَّمَ (öğretti) / فَضَّلَ</text>\n  <text x="256" y="202" font-size="11.5" fill="#1e3a8a">• شَاهَدَ (izledi) / جَاهَدَ</text>\n  <text x="256" y="222" font-size="11.5" fill="#1e3a8a">• أَغْرَقَ (boğdu)</text>\n  <!-- Sag: Mezid 2 ve 3 Harf -->\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">مَزِيدٌ بِحَرْفَيْنِ أَوْ ثَلَاثَةٍ</text>\n  <text x="575" y="86" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">(2 veya 3 Harf Ekli)</text>\n  <rect x="484" y="98" width="182" height="42" rx="6" fill="#fee2e2"/>\n  <text x="575" y="116" text-anchor="middle" font-size="11" font-weight="bold" fill="#7f1d1d">اِفْتَعَلَ / اِنْفَعَلَ / اِسْتَفْعَلَ</text>\n  <text x="575" y="132" text-anchor="middle" font-size="10.5" fill="#991b1b">5 Harfli (Humâsî) &amp; 6 Harfli (Südâsî)</text>\n  <text x="486" y="162" font-size="11.5" fill="#7f1d1d">• اِكْتَسَبَ (kazandı - +2 harf)</text>\n  <text x="486" y="182" font-size="11.5" fill="#7f1d1d">• اِنْكَسَرَ (kırıldı - +2 harf)</text>\n  <text x="486" y="202" font-size="11.5" fill="#7f1d1d">• اِسْتَغْفَرَ (af diledi - +3 harf)</text>\n  <text x="486" y="222" font-size="11.5" fill="#7f1d1d">• اِسْتَقَامَ (dosdoğru oldu - +3)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
